--
-- Table structure for table `payments`
--

DROP TABLE IF EXISTS `payments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `payments` (
  `payment_id` int NOT NULL AUTO_INCREMENT,
  `transaction_type` enum('Lot Purchase','Cremation','Relocation','Renewal','Other') COLLATE utf8mb4_general_ci NOT NULL,
  `reference_id` int DEFAULT NULL,
  `reference_kind` enum('schedule','lot') COLLATE utf8mb4_general_ci DEFAULT NULL,
  `amount` decimal(12,2) NOT NULL,
  `payment_date` date NOT NULL,
  `payment_method` varchar(50) COLLATE utf8mb4_general_ci NOT NULL,
  `receipt_number` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `notes` text COLLATE utf8mb4_general_ci,
  `received_by` int DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `receipt_url` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `gateway_provider` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'Gateway provider identifier (e.g. paymongo); NULL for manual/offline payments',
  `currency` char(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'PHP' COMMENT 'ISO 4217 currency of the payment (PayMongo supports PHP)',
  `gateway_payment_intent_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'PayMongo PaymentIntent id (pi_...) created server-side',
  `gateway_checkout_session_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'PayMongo CheckoutSession id (cs_...) when hosted checkout is used',
  `gateway_payment_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'PayMongo Payment id (pay_...) issued when money actually moved',
  `gateway_status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'Read-only mirror of gateway lifecycle state (awaiting_payment_method/processing/succeeded/failed/...)',
  `verification_status` enum('Pending','Verified','Rejected') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'Pending',
  `verified_by` int DEFAULT NULL,
  `verified_at` datetime DEFAULT NULL,
  PRIMARY KEY (`payment_id`),
  UNIQUE KEY `uq_payment_receipt_number` (`receipt_number`),
  UNIQUE KEY `uq_payment_gateway_payment_intent_id` (`gateway_payment_intent_id`),
  UNIQUE KEY `uq_payment_gateway_checkout_session_id` (`gateway_checkout_session_id`),
  UNIQUE KEY `uq_payment_gateway_payment_id` (`gateway_payment_id`),
  KEY `idx_payment_date` (`payment_date`),
  KEY `fk_payment_received_by` (`received_by`),
  KEY `fk_payment_verified_by` (`verified_by`),
  KEY `idx_payment_reference` (`reference_kind`,`reference_id`),
  KEY `idx_payment_gateway_status` (`gateway_status`),
  CONSTRAINT `fk_payment_received_by` FOREIGN KEY (`received_by`) REFERENCES `users` (`user_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_payment_verified_by` FOREIGN KEY (`verified_by`) REFERENCES `users` (`user_id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=1303 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `payments`
--

LOCK TABLES `payments` WRITE;
/*!40000 ALTER TABLE `payments` DISABLE KEYS */;
