--
-- Table structure for table `refunds`
--

DROP TABLE IF EXISTS `refunds`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `refunds` (
  `refund_id` int NOT NULL AUTO_INCREMENT,
  `payment_id` int NOT NULL,
  `idempotency_key` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `gateway_refund_id` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `gateway_provider` varchar(20) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'paymongo',
  `amount` decimal(12,2) NOT NULL,
  `currency` char(3) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'PHP',
  `status` enum('Pending','Processing','Succeeded','Failed') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'Pending',
  `reason` enum('duplicate','fraudulent','requested_by_customer','others') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'requested_by_customer',
  `notes` text COLLATE utf8mb4_general_ci,
  `requested_by` int DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `processed_at` datetime DEFAULT NULL,
  PRIMARY KEY (`refund_id`),
  UNIQUE KEY `uq_refund_gateway_refund_id` (`gateway_refund_id`),
  UNIQUE KEY `uq_refund_idempotency_key` (`idempotency_key`),
  KEY `idx_refund_payment_id` (`payment_id`),
  KEY `idx_refund_status` (`status`),
  KEY `idx_refund_requested_by` (`requested_by`),
  CONSTRAINT `fk_refund_payment_id` FOREIGN KEY (`payment_id`) REFERENCES `payments` (`payment_id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_refund_requested_by` FOREIGN KEY (`requested_by`) REFERENCES `users` (`user_id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=1131 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

